{"command":"cat <<'EOF' > capture.py
import subprocess
import re

def capture():
    cmd = "tmux new-session -d -s clock_session -x 80 -y 24 './executable -u -c -s' && sleep 1 && tmux capture-pane -e -t clock_session -p && tmux kill-session -t clock_session"
    res = subprocess.check_output(cmd, shell=True).decode()
    return res

def clean(s):
    # Replace green background with # and anything else with .
    # [42m is green background
    # [49m is reset background
    lines = s.split('\n')
    out = []
    for line in lines:
        new_line = ""
        is_green = False
        i = 0
        while i < len(line):
            if line[i:i+5] == '\x1b[42m':
                is_green = True
                i += 5
            elif line[i:i+5] == '\x1b[49m':
                is_green = False
                i += 5
            elif line[i:i+5] == '\x1b[32m': # green text (for date)
                i += 5
            elif line[i:i+5] == '\x1b[39m': # reset text
                i += 5
            else:
                if is_green:
                    new_line += "#"
                else:
                    new_line += "."
                i += 1
        if new_line.strip('.'):
            out.append(new_line)
    return "\n".join(out)

print(clean(capture()))
EOF
