#include "tty-clock.h"
#include "digits.h"

static ttyclock_t TtyClock;
static int running = 1;

void usage(void) {
    printf("usage : tty-clock [-iuvsScbtrahDBxn] [-C [0-7]] [-f format] [-d delay] [-a nsdelay] [-T tty]\n"
           "    -s            Show seconds\n"
           "    -S            Screensaver mode\n"
           "    -x            Show box\n"
           "    -c            Set the clock at the center of the terminal\n"
           "    -C [0-7]      Set the clock color\n"
           "    -b            Use bold colors\n"
           "    -t            Set the hour in 12h format\n"
           "    -u            Use UTC time\n"
           "    -T tty        Display the clock on the specified terminal\n"
           "    -r            Do rebound the clock\n"
           "    -f format     Set the date format\n"
           "    -n            Don't quit on keypress\n"
           "    -v            Show tty-clock version\n"
           "    -i            Show some info about tty-clock\n"
           "    -h            Show this page\n"
           "    -D            Hide date\n"
           "    -B            Enable blinking colon\n"
           "    -d delay      Set the delay between two redraws of the clock. Default 1s.\n"
           "    -a nsdelay    Additional delay between two redraws in nanoseconds. Default 0ns.\n");
}

void version(void) {
    printf("TTY-Clock 2 © devel version\n");
}

void info(void) {
    printf("TTY-Clock 2 © by Martin Duquesnoy (xorg62@gmail.com), Grey (grey@greytheory.net)\n");
}

void init_tty_clock(ttyclock_t *clk) {
    if (clk->tty) {
        FILE *f = fopen(clk->tty, "r+");
        if (!f) {
            perror("fopen");
            exit(1);
        }
        newterm(NULL, f, f);
    } else {
        initscr();
    }
    noecho();
    curs_set(0);
    nodelay(stdscr, TRUE);
    keypad(stdscr, TRUE);
    start_color();
    use_default_colors();

    init_pair(1, clk->color, clk->color);
    init_pair(2, clk->color, -1);
    init_pair(3, COLOR_WHITE, -1); // Default for box
}

void update_time(ttyclock_t *clk) {
    clk->lt = time(NULL);
    if (clk->utc)
        clk->tm = gmtime(&clk->lt);
    else
        clk->tm = localtime(&clk->lt);
}

void draw_digit(int x, int y, int digit, int color_pair) {
    attron(COLOR_PAIR(color_pair));
    for (int r = 0; r < 5; r++) {
        for (int c = 0; c < 3; c++) {
            if (digits[digit][r][c]) {
                mvaddstr(y + r, x + c * 2, "  ");
            }
        }
    }
    attroff(COLOR_PAIR(color_pair));
}

void draw_colon(int x, int y, int hide, int color_pair) {
    if (!hide) {
        attron(COLOR_PAIR(color_pair));
        mvaddstr(y + 1, x + 2, "  ");
        mvaddstr(y + 3, x + 2, "  ");
        attroff(COLOR_PAIR(color_pair));
    }
}

void draw_clock(ttyclock_t *clk) {
    int hour = clk->tm->tm_hour;
    int min = clk->tm->tm_min;
    int sec = clk->tm->tm_sec;
    char ampm[5] = "";

    if (clk->twelve) {
        strcpy(ampm, (hour >= 12) ? " [PM]" : " [AM]");
        if (hour > 12) hour -= 12;
        if (hour == 0) hour = 12;
    }

    int term_w, term_h;
    getmaxyx(stdscr, term_h, term_w);

    clk->w = clk->seconds ? 51 : 32;
    clk->h = 5;

    if (clk->center) {
        clk->x = (term_w - clk->w) / 2;
        clk->y = (term_h - clk->h) / 2;
    } else if (clk->rebound) {
        clk->x += clk->vx;
        clk->y += clk->vy;
        if (clk->x <= 0 || clk->x + clk->w >= term_w) {
            clk->vx = -clk->vx;
            clk->x += 2 * clk->vx;
        }
        if (clk->y <= 0 || clk->y + clk->h >= term_h) { // This boundary might be wrong with box/date
            clk->vy = -clk->vy;
            clk->y += 2 * clk->vy;
        }
    }

    // Adjust boundaries for rebound if box/date are shown
    int total_h = clk->h;
    int total_w = clk->w;
    if (clk->box) {
        total_h += 2;
        total_w += 2;
    }
    if (!clk->nodate) {
        total_h += (clk->box ? 2 : 2);
    }

    // Boundary check for rebound
    if (clk->rebound) {
        int x_min = 0, y_min = 0;
        int x_max = term_w - total_w;
        int y_max = term_h - total_h;
        if (clk->x < x_min) { clk->x = x_min; clk->vx = -clk->vx; }
        if (clk->x > x_max) { clk->x = x_max; clk->vx = -clk->vx; }
        if (clk->y < y_min) { clk->y = y_min; clk->vy = -clk->vy; }
        if (clk->y > y_max) { clk->y = y_max; clk->vy = -clk->vy; }
    }

    erase();

    int dx = clk->x;
    int dy = clk->y;
    if (clk->box) { dx++; dy++; }

    if (clk->bold) attron(A_BOLD);

    // HH
    draw_digit(dx, dy, hour / 10, 1);
    draw_digit(dx + 7, dy, hour % 10, 1);
    // Colon 1
    int blink = (clk->blink && (clk->lt % 2));
    draw_colon(dx + 13, dy, blink, 1);
    // MM
    draw_digit(dx + 19, dy, min / 10, 1);
    draw_digit(dx + 26, dy, min % 10, 1);

    if (clk->seconds) {
        // Colon 2
        draw_colon(dx + 32, dy, blink, 1);
        // SS
        draw_digit(dx + 38, dy, sec / 10, 1);
        draw_digit(dx + 45, dy, sec % 10, 1);
    }

    if (clk->box) {
        // Draw main box
        attron(COLOR_PAIR(3)); // Box is white/default
        // Corners and lines
        mvaddch(clk->y, clk->x, ACS_ULCORNER);
        mvaddch(clk->y, clk->x + total_w - 1, ACS_URCORNER);
        mvaddch(clk->y + clk->h + 1, clk->x, ACS_LLCORNER);
        mvaddch(clk->y + clk->h + 1, clk->x + total_w - 1, ACS_LRCORNER);
        for (int i = 1; i < total_w - 1; i++) {
            mvaddch(clk->y, clk->x + i, ACS_HLINE);
            mvaddch(clk->y + clk->h + 1, clk->x + i, ACS_HLINE);
        }
        for (int i = 1; i < clk->h + 1; i++) {
            mvaddch(clk->y + i, clk->x, ACS_VLINE);
            mvaddch(clk->y + i, clk->x + total_w - 1, ACS_VLINE);
        }
        attroff(COLOR_PAIR(3));
    }

    if (!clk->nodate) {
        char date_str[128];
        strftime(date_str, sizeof(date_str), clk->format, clk->tm);
        strcat(date_str, ampm);
        int date_w = strlen(date_str);
        int date_x, date_y;

        if (clk->box) {
            date_x = clk->x + (total_w - date_w - 2) / 2;
            date_y = clk->y + clk->h + 2;

            attron(COLOR_PAIR(3));
            mvaddch(date_y - 1, date_x, ACS_ULCORNER);
            mvaddch(date_y - 1, date_x + date_w + 1, ACS_URCORNER);
            mvaddch(date_y + 1, date_x, ACS_LLCORNER);
            mvaddch(date_y + 1, date_x + date_w + 1, ACS_LRCORNER);
            mvaddch(date_y, date_x, ACS_VLINE);
            mvaddch(date_y, date_x + date_w + 1, ACS_VLINE);
            for(int i = 1; i <= date_w; i++) mvaddch(date_y + 1, date_x + i, ACS_HLINE);
            // Connect to main box
            mvaddch(clk->y + clk->h + 1, date_x, ACS_TTEE);
            mvaddch(clk->y + clk->h + 1, date_x + date_w + 1, ACS_TTEE);
            attroff(COLOR_PAIR(3));

            attron(COLOR_PAIR(2));
            mvaddstr(date_y, date_x + 1, date_str);
            attroff(COLOR_PAIR(2));
        } else {
            date_x = clk->x + (clk->w - date_w) / 2;
            date_y = clk->y + clk->h + 1;
            attron(COLOR_PAIR(2));
            mvaddstr(date_y, date_x, date_str);
            attroff(COLOR_PAIR(2));
        }
    }

    if (clk->bold) attroff(A_BOLD);

    refresh();
}

int main(int argc, char **argv) {
    ttyclock_t *clk = &TtyClock;
    memset(clk, 0, sizeof(ttyclock_t));
    clk->color = COLOR_GREEN;
