                        clk->rebound = !clk->rebound;
                        break;
                    case 'b':
                    case 'B':
                        clk->bold = !clk->bold;
                        break;
                    case '0': case '1': case '2': case '3':
                    case '4': case '5': case '6': case '7':
                        clk->color = ch - '0';
                        init_pair(1, clk->color, clk->color);
                        init_pair(2, clk->color, -1);
                        break;
                    case 'k': case 'K':
