        int date_x, date_y;
        if (clk->box) {
            date_x = clk->x + (total_w - date_w - 2) / 2;
            date_y = clk->y + clk->h + 3;
            printf("\x0e");
            printf("\e[%d;%dHl", date_y - 1, date_x + 1);
            printf("\e[%d;%dHk", date_y - 1, date_x + date_w + 2);
            printf("\e[%d;%dHm", date_y + 1, date_x + 1);
            printf("\e[%d;%dHj", date_y + 1, date_x + date_w + 2);
            printf("\e[%d;%dHx", date_y, date_x + 1);
            printf("\e[%d;%dHx", date_y, date_x + date_w + 2);
            for(int i = 1; i <= date_w; i++) printf("\e[%d;%dHq", date_y + 1, date_x + i + 1);
            // Connect to main box
            printf("\e[%d;%dHw", clk->y + clk->h + 2, date_x + 1);
            printf("\e[%d;%dHw", clk->y + clk->h + 2, date_x + date_w + 2);
            printf("\x0f");
            if (clk->bold) printf("\e[1m");
            printf("\e[3%dm\e[%d;%dH%s\e[0m", clk->color, date_y, date_x + 2, date_str);
        } else {
            date_x = clk->x + (clk->w - date_w) / 2;
            date_y = clk->y + clk->h + 2;
            if (clk->bold) printf("\e[1m");
            printf("\e[3%dm\e[%d;%dH%s\e[0m", clk->color, date_y, date_x + 1, date_str);
        }
    }
    fflush(stdout);
}

int main(int argc, char **argv) {
    ttyclock_t *clk = &TtyClock;
    memset(clk, 0, sizeof(ttyclock_t));
    clk->color = 2; // Green
    clk->format = "%Y-%m-%d";
    clk->delay = 1;
