{"command":"cat <<'EOF' > tty-clock.c
#include "tty-clock.h"
#include "digits.h"

static ttyclock_t TtyClock;
static int running = 1;

void usage(void) {
    printf("usage : tty-clock [-iuvsScbtrahDBxn] [-C [0-7]] [-f format] [-d delay] [-a nsdelay] [-T tty]\n"
           "    -s            Show seconds\n"
           "    -S            Screensaver mode\n"
           "    -x            Show box\n"
           "    -c            Set the clock at the center of the terminal\n"
           "    -C [0-7]      Set the clock color\n"
           "    -b            Use bold colors\n"
           "    -t            Set the hour in 12h format\n"
           "    -u            Use UTC time\n"
           "    -T tty        Display the clock on the specified terminal\n"
           "    -r            Do rebound the clock\n"
           "    -f format     Set the date format\n"
           "    -n            Don't quit on keypress\n"
           "    -v            Show tty-clock version\n"
           "    -i            Show some info about tty-clock\n"
           "    -h            Show this page\n"
           "    -D            Hide date\n"
           "    -B            Enable blinking colon\n"
           "    -d delay      Set the delay between two redraws of the clock. Default 1s.\n"
           "    -a nsdelay    Additional delay between two redraws in nanoseconds. Default 0ns.\n");
}

void version(void) {
    printf("TTY-Clock 2 © devel version\n");
}

void info(void) {
    printf("TTY-Clock 2 © by Martin Duquesnoy (xorg62@gmail.com), Grey (grey@greytheory.net)\n");
}

void sig_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) running = 0;
    if (sig == SIGWINCH) {
        struct winsize w;
        ioctl(STDOUT_FILENO, TIOCGWINSZ, &w);
        TtyClock.term_w = w.ws_col;
        TtyClock.term_h = w.ws_row;
    }
}

void cleanup(void) {
    tcsetattr(STDIN_FILENO, TCSANOW, &TtyClock.oldterm);
    printf("\e[?25h\e[0m\e[H\e[J");
}

void draw_digit(int x, int y, int digit, int color, int bold) {
    for (int r = 0; r < 5; r++) {
        printf("\e[%d;%dH", y + r + 1, x + 1);
        for (int c = 0; c < 3; c++) {
            if (digits[digit][r][c]) {
                if (bold) printf("\e[1m");
                printf("\e[4%dm  \e[0m", color);
            } else {
                printf("  ");
            }
        }
    }
}

void draw_colon(int x, int y, int hide, int color, int bold) {
    if (!hide) {
        if (bold) printf("\e[1m");
        printf("\e[4%dm", color);
        printf("\e[%d;%dH  ", y + 2, x + 3);
        printf("\e[%d;%dH  ", y + 4, x + 3);
        printf("\e[0m");
    } else {
        printf("\e[%d;%dH  ", y + 2, x + 3);
        printf("\e[%d;%dH  ", y + 4, x + 3);
    }
}

void draw_clock(void) {
    ttyclock_t *clk = &TtyClock;
    clk->lt = time(NULL);
    if (clk->utc) clk->tm = gmtime(&clk->lt);
    else clk->tm = localtime(&clk->lt);

    int hour = clk->tm->tm_hour;
    int min = clk->tm->tm_min;
    int sec = clk->tm->tm_sec;
    char ampm[8] = "";

    if (clk->twelve) {
        strcpy(ampm, (hour >= 12) ? " [PM]" : " [AM]");
        if (hour > 12) hour -= 12;
        if (hour == 0) hour = 12;
    }

    clk->w = clk->seconds ? 51 : 32;
    clk->h = 5;

    int total_w = clk->w;
    int total_h = clk->h;
    if (clk->box) { total_w += 2; total_h += 2; }
    if (!clk->nodate) total_h += 2;

    if (clk->center) {
        clk->x = (clk->term_w - total_w) / 2;
        clk->y = (clk->term_h - total_h) / 2;
    } else if (clk->rebound) {
        clk->x += clk->vx;
        clk->y += clk->vy;
        if (clk->x < 0) { clk->x = 0; clk->vx = -clk->vx; }
        if (clk->x + total_w > clk->term_w) { clk->x = clk->term_w - total_w; clk->vx = -clk->vx; }
        if (clk->y < 0) { clk->y = 0; clk->vy = -clk->vy; }
        if (clk->y + total_h > clk->term_h) { clk->y = clk->term_h - total_h; clk->vy = -clk->vy; }
    }

    printf("\e[H\e[J");

    int dx = clk->x;
    int dy = clk->y;
    if (clk->box) { dx++; dy++; }

    draw_digit(dx, dy, hour / 10, clk->color, clk->bold);
    draw_digit(dx + 7, dy, hour % 10, clk->color, clk->bold);
    int blink = (clk->blink && (clk->lt % 2));
    draw_colon(dx + 13, dy, blink, clk->color, clk->bold);
    draw_digit(dx + 19, dy, min / 10, clk->color, clk->bold);
    draw_digit(dx + 26, dy, min % 10, clk->color, clk->bold);
    if (clk->seconds) {
        draw_colon(dx + 32, dy, blink, clk->color, clk->bold);
        draw_digit(dx + 38, dy, sec / 10, clk->color, clk->bold);
        draw_digit(dx + 45, dy, sec % 10, clk->color, clk->bold);
    }

    if (clk->box) {
        printf("\e[0m\x0e");
        printf("\e[%d;%dHl", clk->y + 1, clk->x + 1);
        printf("\e[%d;%dHk", clk->y + 1, clk->x + total_w);
        printf("\e[%d;%dHm", clk->y + clk->h + 2, clk->x + 1);
        printf("\e[%d;%dHj", clk->y + clk->h + 2, clk->x + total_w);
        for (int i = 1; i < total_w - 1; i++) {
            printf("\e[%d;%dHq", clk->y + 1, clk->x + i + 1);
            printf("\e[%d;%dHq", clk->y + clk->h + 2, clk->x + i + 1);
        }
        for (int i = 0; i < clk->h; i++) {
            printf("\e[%d;%dHx", clk->y + i + 2, clk->x + 1);
            printf("\e[%d;%dHx", clk->y + i + 2, clk->x + total_w);
        }
        printf("\x0f");
    }

    if (!clk->nodate) {
        char date_str[128];
        strftime(date_str, sizeof(date_str), clk->format, clk->tm);
        strcat(date_str, ampm);
        int date_w = strlen(date_str);
        int date_x, date_y;
        if (clk->box) {
            date_x = clk->x + (total_w - date_w - 2) / 2;
            date_y = clk->y + clk->h + 3;
            printf("\x0e");
            printf("\e[%d;%dHl", date_y - 1, date_x + 1);
            printf("\e[%d;%dHk", date_y - 1, date_x + date_w + 2);
            printf("\e[%d;%dHm", date_y + 1, date_x + 1);
            printf("\e[%d;%dHj", date_y + 1, date_x + date_w + 2);
            printf("\e[%d;%dHx", date_y, date_x + 1);
            printf("\e[%d;%dHx", date_y, date_x + date_w + 2);
            for(int i = 1; i <= date_w; i++) printf("\e[%d;%dHq", date_y + 1, date_x + i + 1);
            printf("\e[%d;%dHw", clk->y + clk->h + 2, date_x + 1);
            printf("\e[%d;%dHw", clk->y + clk->h + 2, date_x + date_w + 2);
            printf("\x0f");
            if (clk->bold) printf("\e[1m");
            printf("\e[3%dm\e[%d;%dH%s\e[0m", clk->color, date_y, date_x + 2, date_str);
        } else {
            date_x = clk->x + (clk->w - date_w) / 2;
            date_y = clk->y + clk->h + 2;
            if (clk->bold) printf("\e[1m");
            printf("\e[3%dm\e[%d;%dH%s\e[0m", clk->color, date_y, date_x + 1, date_str);
        }
    }
    fflush(stdout);
}

