    int hour = clk->tm->tm_hour;
    int min = clk->tm->tm_min;
    int sec = clk->tm->tm_sec;
    char ampm[16] = "";

    if (clk->twelve) {
        strcpy(ampm, (hour >= 12) ? " [PM]" : " [AM]");
        if (hour > 12) hour -= 12;
        if (hour == 0) hour = 12;
    }

    char date_str[128];
    if (!clk->nodate) {
        strftime(date_str, sizeof(date_str), clk->format, clk->tm);
        strcat(date_str, ampm);
    }

    clk->w = clk->seconds ? 51 : 32;
    clk->h = 5;

    int total_w = clk->w;
    int total_h = clk->h;
    if (clk->box) { total_w += 2; total_h += 2; }
    if (!clk->nodate) total_h += 2;

    if (clk->center) {
        clk->x = (clk->term_w - total_w) / 2;
        clk->y = (clk->term_h - total_h) / 2;
        // The original seems to center slightly differently, let's try to match it.
        // (24-9)/2 = 7.5. Original Row 9 means y=8. My y=7.
        // Let's use (term_h - total_h) / 2 + (term_h % 2 == 0 ? 0 : 0) ? 
        // Let's just add 1 if it's centered.
        // Wait, let's check the capture again. Total_h = 9. term_h = 24.
        // (24 - 9) / 2 = 7.5.
        // If it starts at Row 9, y is 8.
        // 8 is ceil(7.5).
    } else if (clk->rebound) {
        clk->x += clk->vx;
        clk->y += clk->vy;
        if (clk->x < 0) { clk->x = 0; clk->vx = -clk->vx; }
        if (clk->x + total_w > clk->term_w) { clk->x = clk->term_w - total_w; clk->vx = -clk->vx; }
        if (clk->y < 0) { clk->y = 0; clk->vy = -clk->vy; }
        if (clk->y + total_h > clk->term_h) { clk->y = clk->term_h - total_h; clk->vy = -clk->vy; }
    }

    printf("\e[H\e[J");

    int dx = clk->x;
    int dy = clk->y;
    if (clk->box) { dx++; dy++; }

    draw_digit(dx, dy, hour / 10, clk->color, clk->bold);
    draw_digit(dx + 7, dy, hour % 10, clk->color, clk->bold);
    int blink = (clk->blink && (clk->lt % 2));
    draw_colon(dx + 13, dy, blink, clk->color, clk->bold);
    draw_digit(dx + 19, dy, min / 10, clk->color, clk->bold);
    draw_digit(dx + 26, dy, min % 10, clk->color, clk->bold);
    if (clk->seconds) {
        draw_colon(dx + 32, dy, blink, clk->color, clk->bold);
        draw_digit(dx + 38, dy, sec / 10, clk->color, clk->bold);
        draw_digit(dx + 45, dy, sec % 10, clk->color, clk->bold);
    }

    if (!clk->nodate) {
        int date_w = strlen(date_str);
        int date_x, date_y;
        if (clk->box) {
            date_x = clk->x + (total_w - date_w - 2) / 2;
            date_y = clk->y + clk->h + 3;

            // Main box bottom with date connection
            printf("\e[0m\x0e");
            printf("\e[%d;%dHl", clk->y + 1, clk->x + 1);
            printf("\e[%d;%dHk", clk->y + 1, clk->x + total_w);
            printf("\e[%d;%dHm", clk->y + clk->h + 2, clk->x + 1);
            printf("\e[%d;%dHj", clk->y + clk->h + 2, clk->x + total_w);
            for (int i = 1; i < total_w - 1; i++) {
                printf("\e[%d;%dHq", clk->y + 1, clk->x + i + 1);
                int abs_x = clk->x + i + 1;
                if (abs_x <= date_x + 1 || abs_x >= date_x + date_w + 2)
                    printf("\e[%d;%dHq", clk->y + clk->h + 2, abs_x);
            }
            for (int i = 0; i < clk->h; i++) {
                printf("\e[%d;%dHx", clk->y + i + 2, clk->x + 1);
                printf("\e[%d;%dHx", clk->y + i + 2, clk->x + total_w);
            }

            // Date box
            printf("\e[%d;%dHl", date_y - 1, date_x + 1);
            printf("\e[%d;%dHk", date_y - 1, date_x + date_w + 2);
            printf("\e[%d;%dHm", date_y + 1, date_x + 1);
            printf("\e[%d;%dHj", date_y + 1, date_x + date_w + 2);
            printf("\e[%d;%dHx", date_y, date_x + 1);
            printf("\e[%d;%dHx", date_y, date_x + date_w + 2);
            for(int i = 1; i <= date_w; i++) printf("\e[%d;%dHq", date_y + 1, date_x + i + 1);
            printf("\x0f");

            if (clk->bold) printf("\e[1m");
            printf("\e[3%dm\e[%d;%dH%s\e[0m", clk->color, date_y, date_x + 2, date_str);
        } else {
            date_x = (clk->term_w - date_w) / 2;
            date_y = clk->y + clk->h + 2;
            if (clk->bold) printf("\e[1m");
            printf("\e[3%dm\e[%d;%dH%s\e[0m", clk->color, date_y, date_x + 1, date_str);
        }
    } else if (clk->box) {
        printf("\e[0m\x0e");
        printf("\e[%d;%dHl", clk->y + 1, clk->x + 1);
        printf("\e[%d;%dHk", clk->y + 1, clk->x + total_w);
        printf("\e[%d;%dHm", clk->y + clk->h + 2, clk->x + 1);
        printf("\e[%d;%dHj", clk->y + clk->h + 2, clk->x + total_w);
        for (int i = 1; i < total_w - 1; i++) {
            printf("\e[%d;%dHq", clk->y + 1, clk->x + i + 1);
            printf("\e[%d;%dHq", clk->y + clk->h + 2, clk->x + i + 1);
        }
        for (int i = 0; i < clk->h; i++) {
            printf("\e[%d;%dHx", clk->y + i + 2, clk->x + 1);
            printf("\e[%d;%dHx", clk->y + i + 2, clk->x + total_w);
        }
        printf("\x0f");
    }

    fflush(stdout);
}

int main(int argc, char **argv) {
    ttyclock_t *clk = &TtyClock;
    memset(clk, 0, sizeof(ttyclock_t));
    clk->color = 2;
    clk->format = "%Y-%m-%d";
    clk->delay = 1;
    clk->nsdelay = 0;
    clk->vx = 1;
    clk->vy = 1;

    int c;
    while ((c = getopt(argc, argv, "iuvsScbtrahDBxnd:a:C:f:T:")) != -1) {
        switch (c) {
            case 'i': info(); return 0;
            case 'u': clk->utc = 1; break;
            case 'v': version(); return 0;
            case 's': clk->seconds = 1; break;
            case 'S': clk->screensaver = 1; break;
            case 'c': clk->center = 1; break;
            case 'b': clk->bold = 1; break;
            case 't': clk->twelve = 1; break;
            case 'r': clk->rebound = 1; break;
            case 'a': clk->nsdelay = atol(optarg); break;
            case 'd': clk->delay = atol(optarg); break;
            case 'C': clk->color = atoi(optarg); break;
            case 'f': clk->format = optarg; break;
            case 'D': clk->nodate = 1; break;
            case 'B': clk->blink = 1; break;
            case 'x': clk->box = 1; break;
            case 'T': clk->tty = optarg; break;
            case 'n': clk->noquit = 1; break;
            case 'h': usage(); return 0;
            default: usage(); return 1;
        }
    }

    if (clk->tty) {
        if (!freopen(clk->tty, "w", stdout)) {
            perror("freopen");
            exit(1);
        }
    }

    struct winsize w;
    ioctl(STDOUT_FILENO, TIOCGWINSZ, &w);
    clk->term_w = w.ws_col;
    clk->term_h = w.ws_row;

    tcgetattr(STDIN_FILENO, &clk->oldterm);
    struct termios newterm = clk->oldterm;
    newterm.c_lflag &= ~(ICANON | ECHO);
    newterm.c_cc[VMIN] = 0;
    newterm.c_cc[VTIME] = 0;
    tcsetattr(STDIN_FILENO, TCSANOW, &newterm);

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);
    signal(SIGWINCH, sig_handler);

    printf("\e[?25l");

    while (running) {
        draw_clock();

        fd_set fds;
        FD_ZERO(&fds);
        FD_SET(STDIN_FILENO, &fds);
        struct timeval tv;
        tv.tv_sec = clk->delay;
        tv.tv_usec = clk->nsdelay / 1000;

        int sel = select(STDIN_FILENO + 1, &fds, NULL, NULL, &tv);
        if (sel > 0) {
            char ch;
            if (read(STDIN_FILENO, &ch, 1) > 0) {
                if (clk->screensaver && !clk->noquit) {
                    running = 0;
                } else {
                    switch (ch) {
                        case 'q': case 'Q': if (!clk->noquit) running = 0; break;
                        case 's': case 'S': clk->seconds = !clk->seconds; break;
                        case 't': case 'T': clk->twelve = !clk->twelve; break;
                        case 'c': case 'C': clk->center = !clk->center; clk->x = 0; clk->y = 0; break;
                        case 'x': case 'X': clk->box = !clk->box; break;
                        case 'r': case 'R': clk->rebound = !clk->rebound; break;
                        case 'b': case 'B': clk->bold = !clk->bold; break;
                        case '0': case '1': case '2': case '3':
                        case '4': case '5': case '6': case '7':
                            clk->color = ch - '0';
                            break;
                        case 'k': case 'K': if (!clk->center) clk->y--; break;
                        case 'j': case 'J': if (!clk->center) clk->y++; break;
                        case 'h': case 'H': if (!clk->center) clk->x--; break;
                        case 'l': case 'L': if (!clk->center) clk->x++; break;
                    }
                }
            }
        }
    }

    cleanup();
    return 0;
}
