            default: usage(); return 1;
        }
    }
    if (clk->tty) {
        if (!freopen(clk->tty, "w", stdout)) {
            perror("freopen");
            exit(1);
        }
    }
    struct winsize w;
    ioctl(STDOUT_FILENO, TIOCGWINSZ, &w);
    clk->term_w = w.ws_col;
    clk->term_h = w.ws_row;
    tcgetattr(STDIN_FILENO, &clk->oldterm);
    struct termios newterm = clk->oldterm;
    newterm.c_lflag &= ~(ICANON | ECHO);
    newterm.c_cc[VMIN] = 0;
    newterm.c_cc[VTIME] = 0;
    tcsetattr(STDIN_FILENO, TCSANOW, &newterm);
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);
    signal(SIGWINCH, sig_handler);
    printf("\e[?25l");
    while (running) {
        draw_clock();
        fd_set fds;
        FD_ZERO(&fds);
        FD_SET(STDIN_FILENO, &fds);
        struct timeval tv;
        tv.tv_sec = clk->delay;
        tv.tv_usec = clk->nsdelay / 1000;
        int sel = select(STDIN_FILENO + 1, &fds, NULL, NULL, &tv);
        if (sel > 0) {
            char ch;
            if (read(STDIN_FILENO, &ch, 1) > 0) {
                if (clk->screensaver && !clk->noquit) {
                    running = 0;
                } else {
                    switch (ch) {
                        case 'q': case 'Q': if (!clk->noquit) running = 0; break;
                        case 's': case 'S': clk->seconds = !clk->seconds; break;
                        case 't': case 'T': clk->twelve = !clk->twelve; break;
                        case 'c': case 'C': clk->center = !clk->center; clk->x = 0; clk->y = 0; break;
                        case 'x': case 'X': clk->box = !clk->box; break;
                        case 'r': case 'R': clk->rebound = !clk->rebound; break;
                        case 'b': case 'B': clk->bold = !clk->bold; break;
                        case '0': case '1': case '2': case '3':
                        case '4': case '5': case '6': case '7':
                            clk->color = ch - '0';
                            break;
                        case 'k': case 'K': if (!clk->center) clk->y--; break;
                        case 'j': case 'J': if (!clk->center) clk->y++; break;
                        case 'h': case 'H': if (!clk->center) clk->x--; break;
                        case 'l': case 'L': if (!clk->center) clk->x++; break;
                    }
                }
            }
        }
    }
    cleanup();
    return 0;
}
EOF
cat <<'EOF' > compile.sh
#!/bin/bash
gcc -o executable tty-clock.c
EOF
chmod +x compile.sh
./compile.sh
"}
